import java.util.Calendar;
import java.util.Date;
import java.text.SimpleDateFormat;
import java.text.ParseException;

public class Probe {
    public static void main(String[] args) throws Exception {
        // toCalendar(null)
        try {
            Calendar c = Calendar.getInstance();
            c.setTime(null);
            System.out.println("setTime(null) did not throw");
        } catch (NullPointerException e) {
            System.out.println("setTime(null) threw NPE");
        }

        // non-lenient set invalid day
        try {
            Calendar c = Calendar.getInstance();
            c.setLenient(false);
            c.setTime(new Date());
            c.set(Calendar.DAY_OF_MONTH, 31);
            c.set(Calendar.MONTH, Calendar.FEBRUARY);
            Date d = c.getTime();
            System.out.println("non-lenient Feb 31 did not throw: " + d);
        } catch (IllegalArgumentException e) {
            System.out.println("non-lenient Feb 31 threw IAE: " + e.getMessage());
        }

        // strict parse
        try {
            SimpleDateFormat sdf = new SimpleDateFormat("MM/dd/yyyy");
            sdf.setLenient(false);
            Date d = sdf.parse("02/30/2008");
            System.out.println("strict parse Feb 30 did not throw: " + d);
        } catch (ParseException e) {
            System.out.println("strict parse Feb 30 threw ParseException");
        }

        // lenient parse of same
        SimpleDateFormat sdf2 = new SimpleDateFormat("MM/dd/yyyy");
        sdf2.setLenient(true);
        Date d2 = sdf2.parse("02/30/2008");
        System.out.println("lenient parse Feb 30: " + d2);
    }
}
